// Moves the focus to the element as soon as it is rendered.
angular.module("castra.core")
    .directive("autoFocus", Directive);

Directive.$inject = [ "$timeout" ];

function Directive ($timeout) {
    return {
        restrict: "A",
        link    : link
    };

    function link (scope, element, attrs) {
        $timeout(function () {
            element[0].focus();
        });
    }
}

===== src/app/ajs/directives/confirm-click.js
// Asks before it runs the expression of a click.
angular.module("castra.core")
    .directive("confirmClick", Directive);

Directive.$inject = [ "$window" ];

function Directive ($window) {
    return {
        restrict: "A",
        link    : link
    };

    function link (scope, element, attrs) {
        element.on("click", function () {
            if ($window.confirm(attrs.confirmMessage || "Are you sure?")) {
                scope.$apply(attrs.confirmClick);
            }
        });
    }
}

===== src/app/ajs/directives/sticky-header.js
// Keeps the head of a long list in view while the page scrolls.
angular.module("castra.core")
    .directive("stickyHeader", Directive);

Directive.$inject = [ "$window", "$document" ];

function Directive ($window, $document) {
    return {
        restrict: "A",
        link    : link
    };

    function link (scope, element, attrs) {
        var offset = attrs.stickyHeader === "top" ? 0 : 48;
        angular.element($window).on("scroll", function () {
            element.toggleClass("is-stuck", $document[0].documentElement.scrollTop > offset);
        });
    }
}

